}

template <typename CInsn, typename CInsnOp>
std::pair<llvm::Value*, llvm::Value*>
Capstone2LlvmIrTranslator_impl<CInsn, CInsnOp>::loadOpBinary(
		CInsn* ci,
		llvm::IRBuilder<>& irb,
