FileImage::FileImage(
		llvm::Module* m,
		std::unique_ptr<retdec::loader::Image> img,
		Config* config)
		:
		_module(m),
		_image(std::move(img))
{
	if (_image == nullptr)
	{
		_image.reset();
		throw std::runtime_error("Failed to load input file");
	}

	auto& c = config->getConfig();
	auto& ca = c.architecture;
	auto endian = ca.isEndianUnknown()
			? _image->getEndianness()
			: (ca.isEndianLittle()
					? retdec::utils::Endianness::LITTLE
					: retdec::utils::Endianness::BIG);
	auto arch = retdec::fileformat::Architecture::UNKNOWN;
	if (ca.isX86()) arch = retdec::fileformat::Architecture::X86;
	if (ca.isX86_64()) arch = retdec::fileformat::Architecture::X86_64;
	if (ca.isArm32OrThumb()) arch = retdec::fileformat::Architecture::ARM;
	if (ca.isPpc()) arch = retdec::fileformat::Architecture::POWERPC;
	if (ca.isMipsOrPic32()) arch = retdec::fileformat::Architecture::MIPS;

	_image->getFileFormat()->initArchitecture(
			arch,
			endian,
			c.architecture.getByteSize(),
			c.parameters.getEntryPoint(),
			c.parameters.getSectionVMA());

	if (auto* imgRaw = dynamic_cast<retdec::loader::RawDataImage*>(
			_image.get()))
	{
		imgRaw->reload();
	}

	if (_image->getSegments().empty()
			|| _image->getByteLength() == 0
			|| _image->getBytesPerWord() == 0
			|| _image->getWordLength() == 0)
	{
		throw std::runtime_error("Missing basic info about input file"
				" -> there can be no decompilation");
	}

bool SyscallFixer::runOnModuleCustom(
		llvm::Module& M,
		Config* c,
		FileImage* img,
		Lti* lti,
		Abi* abi)
{
	_module = &M;
	_config = c;
	_image = img;
	_lti = lti;
	_abi = abi;
	return run();
}

bool SyscallFixer::run()
{
	if (_config == nullptr)
	{
		return false;
	}

	if (_config->getConfig().architecture.isMipsOrPic32())
	{
		return runMips();
	}
	else if (_config->getConfig().architecture.isArm32OrThumb())
	{
		return runArm();
	}
	else if (_config->getConfig().architecture.isArm64())
	{
		return runArm64();
	}
	else if (_config->getConfig().architecture.isX86_32())
	{
		return runX86();
	}
	else
	{
		return false;
	}
}

bool SyscallFixer::transform(
		AsmInstruction ai,
		uint64_t code,
		const std::map<uint64_t, std::string>& codeMap)
{
	// Find syscall name.
	//
	auto fit = codeMap.find(code);
	if (fit == codeMap.end())
	{
		LOG << "\tno syscall entry for code" << std::endl;
		case CallingConvention::eCC::CC_STDCALL:  out << "CC_STDCALL"; break;
		case CallingConvention::eCC::CC_PASCAL:   out << "CC_PASCAL"; break;
		case CallingConvention::eCC::CC_FASTCALL: out << "CC_FASTCALL"; break;
		case CallingConvention::eCC::CC_THISCALL: out << "CC_THISCALL"; break;
		case CallingConvention::eCC::CC_MANUAL:   out << "CC_MANUAL"; break;
		case CallingConvention::eCC::CC_SPOILED:  out << "CC_SPOILED"; break;
		case CallingConvention::eCC::CC_SPECIALE: out << "CC_SPECIALE"; break;
		case CallingConvention::eCC::CC_SPECIALP: out << "CC_SPECIALP"; break;
		case CallingConvention::eCC::CC_SPECIAL:  out << "CC_SPECIAL"; break;
		case CallingConvention::eCC::CC_WATCOM:   out << "CC_WATCOM"; break;
		case CallingConvention::eCC::CC_X64:      out << "CC_X64_OS_DEFAULT"; break;
		case CallingConvention::eCC::CC_ARM:      out << "CC_ARM_DEFAULT"; break;
		case CallingConvention::eCC::CC_ARM64:    out << "CC_ARM64_DEFAULT"; break;
		case CallingConvention::eCC::CC_MIPS:     out << "CC_MIPS_DEFAULT"; break;
		case CallingConvention::eCC::CC_MIPS64:   out << "CC_MIPS64_DEFAULT"; break;
		case CallingConvention::eCC::CC_POWERPC:  out << "CC_POWERPC_DEFAULT"; break;
		case CallingConvention::eCC::CC_POWERPC64:out << "CC_POWERPC64_DEFAULT"; break;
		case CallingConvention::eCC::CC_PIC32:    out << "CC_PIC32_DEFAULT"; break;
		default: out << "UNHANDLED"; break;
	}
	return out;
}

std::ostream& operator<<(std::ostream &out, const CallingConvention& cc)
{
	out << cc._cc;

	return out;
}

