bool SyscallFixer::run()
{
	if (_config == nullptr)
	{
		return false;
	}

	if (_config->getConfig().architecture.isMipsOrPic32())
	{
		return runMips();
	}
	else if (_config->getConfig().architecture.isArm32OrThumb())
	{
		return runArm();
	}
	else if (_config->getConfig().architecture.isArm64())
	{
		return runArm64();
	}
	else if (_config->getConfig().architecture.isX86_32())
	{
		return runX86();
	}
	else
	{
		return false;
	}
}

