+	auto* rhsBits = irb.CreateBitCast(rhs, bitsType);
+	auto* signMask = getSignedInt(
+			irb.getIntNTy(lhs->getType()->getPrimitiveSizeInBits()),
+			1ULL << (bitsType->getIntegerBitWidth() - 1));
