void Capstone2LlvmIrTranslatorRiscV_impl::translateAdd(
		cs_insn*,
		cs_riscv* ci,
		llvm::IRBuilder<>& irb)
{
	EXPECT_IS_BINARY_OR_TERNARY(_insn, ci, irb);
	auto values = loadOpBinaryOrTernaryOp1Op2(ci, irb);
